def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    stack = [(r, c) for r in range(h) for c in range(w)
             if (r == 0 or r == h - 1 or c == 0 or c == w - 1)
             and grid[r][c] == 6]
    while stack:
        r, c = stack.pop()
        if (r, c) in seen:
            continue
        seen.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 6 and (nr, nc) not in seen:
                stack.append((nr, nc))
    return [[4 if grid[r][c] == 6 and (r, c) not in seen else grid[r][c]
             for c in range(w)] for r in range(h)]
